// ❌ a new controller on every build — the text resets and nothing disposes it
class BadForm extends StatelessWidget {
  const BadForm({super.key});

  @override
  Widget build(BuildContext context) {
    final controller = TextEditingController();   // recreated each build
    return TextField(controller: controller);
  }
}

// ✅ the controller is State: created once, released once
class GoodForm extends StatefulWidget {
  const GoodForm({super.key});
  @override
  State<GoodForm> createState() => _GoodFormState();
}

class _GoodFormState extends State<GoodForm> {
  final _name = TextEditingController(text: 'Ada');

  @override
  void dispose() {
    _name.dispose();     // a ValueNotifier: its listeners die with it
    super.dispose();
  }

  void _prefill(String value) {
    _name.text = value;  // caret jumps to the end, onChanged does NOT fire
  }

  void _selectAll() {
    _name.selection =
        TextSelection(baseOffset: 0, extentOffset: _name.text.length);
  }

  @override
  Widget build(BuildContext context) => TextField(
        controller: _name,
        decoration: const InputDecoration(labelText: 'Name'),
      );
}

class _SearchState extends State<Search> {
  final _query = TextEditingController();
  String _lastQuery = '';
  bool _typing = false;
  Timer? _debounce;

  @override
  void initState() {
    super.initState();
    _query.addListener(_onValueChanged);
  }

  // Also fires on caret moves and programmatic writes — guard against both.
  void _onValueChanged() {
    if (_query.text == _lastQuery) return;   // selection-only change: ignore
    _lastQuery = _query.text;
    _debounce?.cancel();
    _debounce = Timer(
      const Duration(milliseconds: 300),
      () => _search(_lastQuery),
    );
  }

  @override
  void dispose() {
    _debounce?.cancel();
    _query.removeListener(_onValueChanged);
    _query.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => TextField(
        controller: _query,
        textInputAction: TextInputAction.search,
        // Simpler when only user edits matter — no controller needed for this.
        onChanged: (text) => setState(() => _typing = text.isNotEmpty),
        onSubmitted: _search,   // the keyboard's search key
      );
}

