class _CheckoutState extends State<Checkout> {
  final _formKey = GlobalKey<FormState>();
  Order _order = const Order();      // filled by onSaved, not by save() itself

  void _submit() {
    final form = _formKey.currentState!;   // null before the first build
    final invalid = form.validateGranularly();   // validates AND names the losers
    if (invalid.isNotEmpty) {
      Scrollable.ensureVisible(invalid.first.context);  // first failing field
      return;
    }
    form.save();                     // only now do the onSaved callbacks run
    _api.place(_order);
  }

  @override
  Widget build(BuildContext context) => Form(
        key: _formKey,
        child: Column(
          children: [
            TextFormField(
              initialValue: _order.street,
              validator: (v) =>
                  (v ?? '').isEmpty ? 'Street is required' : null,
              onSaved: (v) => _order = _order.copyWith(street: v!),
            ),
            // ❌ a nested Form is its own FormState — the outer validate()
            //    never reaches this validator, and save() never reaches it either
            Form(
              child: TextFormField(validator: _neverRuns),
            ),
            FilledButton(onPressed: _submit, child: const Text('Place order')),
          ],
        ),
      );
}

