class _LoginState extends State<Login> {
  final _email = FocusNode();
  final _password = FocusNode();

  @override
  void dispose() {
    _email.dispose();      // nodes are yours to release, exactly like controllers
    _password.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => GestureDetector(
        // touch platforms will not dismiss the keyboard for you
        behavior: HitTestBehavior.opaque,
        onTap: () => FocusScope.of(context).unfocus(),
        child: Column(
          children: [
            TextField(
              focusNode: _email,
              autofocus: true,
              textInputAction: TextInputAction.next,     // -> nextFocus()
              onSubmitted: (_) => _password.requestFocus(),  // explicit hop
            ),
            TextField(
              focusNode: _password,
              obscureText: true,
              textInputAction: TextInputAction.done,
              onSubmitted: (_) => _submit(),
            ),
          ],
        ),
      );
}

