class _UsernameFieldState extends State<UsernameField> {
  final _controller = TextEditingController();
  Timer? _debounce;
  int _request = 0;
  String? _taken;        // the message the synchronous validator will hand back
  bool _checking = false;

  void _onChanged(String value) {
    _taken = null;                    // the old verdict is about the old text
    _debounce?.cancel();
    _debounce = Timer(const Duration(milliseconds: 400), () => _check(value));
  }

  Future<void> _check(String name) async {
    if (name.length < 3) return;
    final token = ++_request;         // only the newest reply may win
    setState(() => _checking = true);
    final free = await api.isUsernameFree(name);
    if (!mounted || token != _request) return;   // stale response: drop it
    setState(() {
      _checking = false;
      _taken = free ? null : '$name is already taken';
    });
  }

  @override
  void dispose() {
    _debounce?.cancel();
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => TextFormField(
        controller: _controller,
        onChanged: _onChanged,
        autovalidateMode: AutovalidateMode.onUserInteraction,
        decoration: InputDecoration(
          labelText: 'Username',
          helperText: ' ',
          suffixIcon: _checking ? const _Spinner() : null,
        ),
        // Synchronous by contract: it reports, it does not go and find out.
        validator: (v) =>
            (v ?? '').length < 3 ? 'At least 3 characters' : _taken,
      );
}

class ThousandsFormatter extends TextInputFormatter {
  static final _digit = RegExp(r'[0-9]');

  @override
  TextEditingValue formatEditUpdate(TextEditingValue old, TextEditingValue next) {
    final digits = next.text.replaceAll(RegExp(r'[^0-9]'), '');
    if (digits.isEmpty) return const TextEditingValue();

    final grouped = _group(digits);
    final caret = next.selection.baseOffset.clamp(0, next.text.length);

    // How many digits did the user have to the LEFT of the caret?
    final before = next.text.substring(0, caret).replaceAll(RegExp(r'[^0-9]'), '').length;

    // Walk the masked string until we have passed that many digits.
    var seen = 0;
    var offset = grouped.length;
    for (var i = 0; i < grouped.length; i++) {
      if (seen == before) {
        offset = i;
        break;
      }
      if (_digit.hasMatch(grouped[i])) seen++;
    }

    // ❌ offset: grouped.length here — this is what pins the caret to the end
    return TextEditingValue(
      text: grouped,
      selection: TextSelection.collapsed(offset: offset),
      // composing left empty on purpose: the old range no longer matches
    );
  }

  String _group(String digits) {
    final b = StringBuffer();
    for (var i = 0; i < digits.length; i++) {
      if (i > 0 && (digits.length - i) % 3 == 0) b.write(' ');
      b.write(digits[i]);
    }
    return b.toString();
  }
}

