class DateFormField extends FormField<DateTime> {
  DateFormField({
    super.key,
    super.initialValue,
    super.validator,
    super.onSaved,
    super.autovalidateMode = AutovalidateMode.onUserInteraction,
    required String label,
  }) : super(
          builder: (FormFieldState<DateTime> state) {
            final value = state.value;
            return InkWell(
              onTap: () async {
                final picked = await showDatePicker(
                  context: state.context,
                  initialDate: value ?? DateTime.now(),
                  firstDate: DateTime(1900),
                  lastDate: DateTime(2100),
                );
                // didChange, NOT setState: this is what updates the Form
                if (picked != null) state.didChange(picked);
              },
              child: InputDecorator(
                isEmpty: value == null,          // lets the label float correctly
                decoration: InputDecoration(
                  labelText: label,
                  errorText: state.errorText,    // Material error styling, free
                ),
                child: Text(value == null
                    ? ''
                    : MaterialLocalizations.of(state.context).formatMediumDate(value)),
              ),
            );
          },
        );
}

