// ✅ the controller owns text + caret; state comes back only as decoration
class _SearchFieldState extends State<SearchField> {
  final _ctrl = TextEditingController();

  @override
  void dispose() {
    _ctrl.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return BlocConsumer<SearchBloc, SearchState>(
      listenWhen: (a, b) => a.query != b.query,
      listener: (context, state) {
        if (state.query == _ctrl.text) return;   // ignore our own echo
        _ctrl.value = _ctrl.value.copyWith(      // external change only
          text: state.query,
          selection: TextSelection.collapsed(offset: state.query.length),
          composing: TextRange.empty,
        );
      },
      builder: (context, state) => TextField(
        controller: _ctrl,
        decoration: InputDecoration(errorText: state.error),
        onChanged: (v) => context.read<SearchBloc>().add(QueryChanged(v)),
      ),
    );
  }
}

