class _SignupPageState extends State<SignupPage> with RestorationMixin {
  // Survives a rebuild AND process death; a plain controller only survives rebuilds.
  final RestorableTextEditingController _email = RestorableTextEditingController();
  final RestorableBool _newsletter = RestorableBool(false);

  @override
  String? get restorationId => 'signup';   // null opts this subtree out

  @override
  void restoreState(RestorationBucket? oldBucket, bool initialRestore) {
    registerForRestoration(_email, 'email');
    registerForRestoration(_newsletter, 'newsletter');
  }

  @override
  void dispose() {
    _email.dispose();
    _newsletter.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => Column(
        children: [
          TextField(controller: _email.value),  // .value IS the controller
          SwitchListTile(
            value: _newsletter.value,
            onChanged: (v) => setState(() => _newsletter.value = v),
            title: const Text('Send me news'),
          ),
        ],
      );
}

