// ✅ the page owns the values; a row is just a view of one
class _LongFormState extends State<LongForm> {
  final _formKey = GlobalKey<FormState>();
  late final Map<String, TextEditingController> _ctrls = {
    for (final f in widget.fields) f.id: TextEditingController(text: f.initial),
  };

  @override
  void dispose() {
    for (final c in _ctrls.values) c.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => Form(
        key: _formKey,
        child: ListView.builder(
          itemCount: widget.fields.length,
          itemBuilder: (_, i) {
            final f = widget.fields[i];
            return TextFormField(
              controller: _ctrls[f.id],       // outlives the row widget
              validator: f.validator,
              decoration: InputDecoration(labelText: f.label),
            );
          },
        ),
      );
}

