// ❌ rewrites text mid-composition and keeps a range that no longer fits it
class ShoutFormatter extends TextInputFormatter {
  @override
  TextEditingValue formatEditUpdate(TextEditingValue old, TextEditingValue next) {
    return TextEditingValue(
      text: next.text.toUpperCase(),
      selection: next.selection,   // stale if the length changed
      composing: next.composing,   // now points into rewritten text
    );
  }
}

// ✅ leave the IME alone until it commits, then rewrite carefully
class SafeShoutFormatter extends TextInputFormatter {
  @override
  TextEditingValue formatEditUpdate(TextEditingValue old, TextEditingValue next) {
    if (next.composing.isValid) return next;   // mid-word in Japanese or Korean
    final upper = next.text.toUpperCase();
    return next.copyWith(
      text: upper,
      selection: TextSelection.collapsed(
        offset: next.selection.baseOffset.clamp(0, upper.length),
      ),
      composing: TextRange.empty,              // we changed the text, so drop it
    );
  }
}

// Counting what the user sees, not what UTF-16 stores
const typed = '👍🏽 ok';
typed.length;              // 7 code units
typed.characters.length;   // 4 grapheme clusters

// ❌ can split a surrogate pair into two broken squares
final bad = typed.substring(0, 3);
// ✅ always lands on a character boundary
